import{describe,it,expect}from"vitest";import{indianEmpiresData,getEmpireById,filterEmpires,getEmpireStageMapData,filterEmpiresByEra}from"../../frontend/indian-empires-explorer/empires-timeline.js";const REQUIRED_EMPIRE_FIELDS=["id","name","period","era","region","capital","peakAreaKm","keyRulers","expansionDetails","declineFactors","mapStages"];describe("Indian Empires Dataset Integrity",()=>{it("contains exactly 10 major empires/civilizations as specified",()=>{expect(indianEmpiresData.length).toBe(10);const e=indianEmpiresData.map(e=>e.name);expect(e).toContain("Indus Valley Civilization"),expect(e).toContain("Mahajanapadas"),expect(e).toContain("Maurya Empire"),expect(e).toContain("Gupta Empire"),expect(e).toContain("Chalukya Dynasty"),expect(e).toContain("Chola Empire"),expect(e).toContain("Vijayanagara Empire"),expect(e).toContain("Mughal Empire"),expect(e).toContain("Maratha Empire"),expect(e).toContain("Sikh Empire")}),it("every empire entry contains required fields with valid content",()=>{indianEmpiresData.forEach((e,t)=>{REQUIRED_EMPIRE_FIELDS.forEach(a=>{expect(e,`Empire at index ${t} missing field ${a}`).toHaveProperty(a)}),expect(e.keyRulers.length).toBeGreaterThan(0),expect(e.expansionDetails.length).toBeGreaterThan(15),expect(e.declineFactors.length).toBeGreaterThan(15),expect(e.mapStages).toHaveProperty("foundation"),expect(e.mapStages).toHaveProperty("peak"),expect(e.mapStages).toHaveProperty("decline")})}),it("all empire IDs are unique",()=>{const e=indianEmpiresData.map(e=>e.id);expect(new Set(e).size).toBe(e.length)})}),describe("Empire Query Helpers & Search Engine",()=>{it("retrieves an empire by ID or name",()=>{const e=getEmpireById("empire-maurya");expect(e).toBeDefined(),expect(e.name).toBe("Maurya Empire");const t=getEmpireById("Chola");expect(t).toBeDefined(),expect(t.capital).toContain("Thanjavur")}),it("filters empires by era",()=>{const e=filterEmpiresByEra("Ancient");expect(e.length).toBeGreaterThan(0),expect(e.every(e=>"Ancient"===e.era)).toBe(!0)}),it("filters empires by search query (e.g. Akbar, Harappa, Hampi, Panipat)",()=>{const e=filterEmpires("Akbar");expect(e.length).toBe(1),expect(e[0].name).toBe("Mughal Empire");const t=filterEmpires("Hampi");expect(t.length).toBe(1),expect(t[0].name).toBe("Vijayanagara Empire")}),it("returns empty array when search query matches nothing",()=>{const e=filterEmpires("NonExistentEmpireXYZ");expect(e).toEqual([])})}),describe("Territorial Map Stage Data Generator",()=>{it("returns valid SVG map path data for foundation, peak, and decline stages",()=>{const e=getEmpireStageMapData("empire-maurya","peak");expect(e).toBeDefined(),expect(e.stage).toBe("peak"),expect(e.path).toContain("M");const t=getEmpireStageMapData("empire-maratha","decline");expect(t).toBeDefined(),expect(t.stage).toBe("decline"),expect(t.path).toContain("M")}),it("defaults to peak stage if an invalid stage is passed",()=>{const e=getEmpireStageMapData("empire-gupta","invalidStage");expect(e.stage).toBe("peak")})});